{
  "name": "Nano Banana Pro: Background Reimagined",
  "description": "A sophisticated AI-powered tool that seamlessly replaces backgrounds in your images using the advanced Gemini 3 Pro Image model. Simply upload an image and describe your dream setting.",
  "requestFramePermissions": [
    "camera"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface GenerationState {
  isGenerating: boolean;
  error: string | null;
  resultUrl: string | null;
}

export interface ImagePreview {
  file: File;
  previewUrl: string;
}

declare global {
  interface Window {
    aistudio: {
      hasSelectedApiKey: () => Promise<boolean>;
      openSelectKey: () => Promise<void>;
    };
  }
}

import { GoogleGenAI } from "@google/genai";

export const MODEL_NAME = 'gemini-3-pro-image-preview';

export async function editImageBackground(
  imageContent: string, 
  prompt: string,
  aspectRatio: "1:1" | "3:4" | "4:3" | "9:16" | "16:9" = "1:1"
): Promise<string> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const systemInstruction = "You are an expert image editor. Your task is to accurately remove the background from the provided image and replace it with a new background based on the user's description. The subject of the original image must remain identical in terms of lighting, focus, and pose. The new background should blend seamlessly with the subject, ensuring natural-looking shadows and edge transitions.";

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: {
        parts: [
          {
            inlineData: {
              data: imageContent.split(',')[1], // Remove the data:image/png;base64, prefix
              mimeType: 'image/png',
            },
          },
          {
            text: `Remove the background from this image and replace it with: ${prompt}. Ensure seamless blending.`,
          },
        ],
      },
      config: {
        imageConfig: {
          aspectRatio,
          imageSize: "1K"
        }
      }
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }

    throw new Error("No image was generated by the model.");
  } catch (error: any) {
    if (error.message?.includes("Requested entity was not found")) {
      throw new Error("API_KEY_EXPIRED");
    }
    throw error;
  }
}

export async function fileToBase64(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = (error) => reject(error);
  });
}

import React from 'react';

interface ApiKeyGateProps {
  onSuccess: () => void;
}

const ApiKeyGate: React.FC<ApiKeyGateProps> = ({ onSuccess }) => {
  const handleSelectKey = async () => {
    try {
      await window.aistudio.openSelectKey();
      // Assume success as per guidelines to avoid race condition
      onSuccess();
    } catch (err) {
      console.error("Failed to open key selector", err);
    }
  };

  return (
    <div className="flex flex-col items-center justify-center min-h-[60vh] text-center px-4">
      <div className="bg-slate-800 p-8 rounded-2xl border border-slate-700 shadow-2xl max-w-md w-full">
        <div className="w-16 h-16 bg-blue-600 rounded-full flex items-center justify-center mx-auto mb-6">
          <i className="fa-solid fa-key text-2xl text-white"></i>
        </div>
        <h2 className="text-2xl font-bold mb-4">API Key Required</h2>
        <p className="text-slate-400 mb-8">
          The Gemini 3 Pro Image model requires a personal API key from a paid Google Cloud project. 
          Please select your key to continue.
        </p>
        <button
          onClick={handleSelectKey}
          className="w-full bg-blue-600 hover:bg-blue-700 text-white font-semibold py-3 px-6 rounded-xl transition-all flex items-center justify-center gap-2 group"
        >
          Select API Key
          <i className="fa-solid fa-arrow-right group-hover:translate-x-1 transition-transform"></i>
        </button>
        <p className="mt-4 text-xs text-slate-500">
          Learn about <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" rel="noopener noreferrer" className="underline hover:text-blue-400">billing and quotas</a>.
        </p>
      </div>
    </div>
  );
};

export default ApiKeyGate;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import ApiKeyGate from './components/ApiKeyGate';
import { editImageBackground, fileToBase64 } from './services/geminiService';
import { ImagePreview, GenerationState } from './types';

const App: React.FC = () => {
  const [hasKey, setHasKey] = useState<boolean | null>(null);
  const [sourceImage, setSourceImage] = useState<ImagePreview | null>(null);
  const [prompt, setPrompt] = useState<string>('');
  const [generation, setGeneration] = useState<GenerationState>({
    isGenerating: false,
    error: null,
    resultUrl: null,
  });
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const checkKey = async () => {
      const selected = await window.aistudio.hasSelectedApiKey();
      setHasKey(selected);
    };
    checkKey();
  }, []);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (sourceImage?.previewUrl) URL.revokeObjectURL(sourceImage.previewUrl);
      setSourceImage({
        file,
        previewUrl: URL.createObjectURL(file),
      });
      setGeneration(prev => ({ ...prev, resultUrl: null, error: null }));
    }
  };

  const handleGenerate = async () => {
    if (!sourceImage || !prompt.trim()) return;

    setGeneration({ isGenerating: true, error: null, resultUrl: null });

    try {
      const base64 = await fileToBase64(sourceImage.file);
      const result = await editImageBackground(base64, prompt);
      setGeneration({ isGenerating: false, error: null, resultUrl: result });
    } catch (err: any) {
      if (err.message === "API_KEY_EXPIRED") {
        setHasKey(false);
      }
      setGeneration({
        isGenerating: false,
        error: err.message || "Failed to reimagine background. Please try again.",
        resultUrl: null,
      });
    }
  };

  const handleReset = () => {
    setSourceImage(null);
    setPrompt('');
    setGeneration({ isGenerating: false, error: null, resultUrl: null });
  };

  if (hasKey === null) return <div className="min-h-screen bg-slate-950 flex items-center justify-center"><i className="fa-solid fa-spinner fa-spin text-4xl text-blue-500"></i></div>;
  if (hasKey === false) return <div className="min-h-screen bg-slate-950 pt-20"><ApiKeyGate onSuccess={() => setHasKey(true)} /></div>;

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 pb-20">
      {/* Header */}
      <header className="border-b border-slate-800 bg-slate-900/50 backdrop-blur-md sticky top-0 z-10">
        <div className="max-w-6xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-yellow-400 rounded-lg flex items-center justify-center">
              <i className="fa-solid fa-wand-magic-sparkles text-slate-900"></i>
            </div>
            <h1 className="text-xl font-bold tracking-tight">Nano Banana <span className="text-yellow-400">Pro</span></h1>
          </div>
          <button 
            onClick={() => window.aistudio.openSelectKey()}
            className="text-xs text-slate-400 hover:text-white flex items-center gap-1 transition-colors"
          >
            <i className="fa-solid fa-cog"></i> Change Key
          </button>
        </div>
      </header>

      <main className="max-w-6xl mx-auto px-4 mt-8 lg:mt-12">
        <div className="text-center mb-12">
          <h2 className="text-3xl lg:text-5xl font-extrabold mb-4 bg-gradient-to-r from-white to-slate-500 bg-clip-text text-transparent">
            Background Reimagined
          </h2>
          <p className="text-slate-400 max-w-2xl mx-auto text-lg">
            Effortlessly remove and replace backgrounds using Gemini 3 Pro's advanced image editing capabilities.
          </p>
        </div>

        <div className="grid lg:grid-cols-2 gap-8 items-start">
          {/* Left Side: Upload & Prompt */}
          <div className="space-y-6">
            <div className="bg-slate-900 p-6 rounded-3xl border border-slate-800 shadow-xl">
              <label className="block text-sm font-medium text-slate-300 mb-4 flex items-center gap-2">
                <i className="fa-solid fa-image text-blue-400"></i> 1. Upload Source Image
              </label>

              {!sourceImage ? (
                <div 
                  onClick={() => fileInputRef.current?.click()}
                  className="border-2 border-dashed border-slate-700 rounded-2xl h-64 flex flex-col items-center justify-center cursor-pointer hover:border-blue-500 hover:bg-slate-800/50 transition-all group"
                >
                  <div className="w-16 h-16 bg-slate-800 rounded-full flex items-center justify-center mb-4 group-hover:scale-110 transition-transform">
                    <i className="fa-solid fa-cloud-arrow-up text-2xl text-slate-400 group-hover:text-blue-400"></i>
                  </div>
                  <p className="text-slate-400 font-medium">Click to upload image</p>
                  <p className="text-xs text-slate-500 mt-2">Supports JPG, PNG (Max 5MB)</p>
                  <input 
                    type="file" 
                    ref={fileInputRef} 
                    className="hidden" 
                    accept="image/*"
                    onChange={handleFileChange}
                  />
                </div>
              ) : (
                <div className="relative group rounded-2xl overflow-hidden ring-1 ring-slate-700">
                  <img src={sourceImage.previewUrl} alt="Source" className="w-full h-auto max-h-80 object-contain bg-slate-800" />
                  <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                    <button 
                      onClick={() => fileInputRef.current?.click()}
                      className="bg-white text-slate-900 px-4 py-2 rounded-lg font-bold text-sm flex items-center gap-2"
                    >
                      <i className="fa-solid fa-rotate"></i> Replace Image
                    </button>
                  </div>
                  <input 
                    type="file" 
                    ref={fileInputRef} 
                    className="hidden" 
                    accept="image/*"
                    onChange={handleFileChange}
                  />
                </div>
              )}
            </div>

            <div className="bg-slate-900 p-6 rounded-3xl border border-slate-800 shadow-xl">
              <label className="block text-sm font-medium text-slate-300 mb-4 flex items-center gap-2">
                <i className="fa-solid fa-pen-nib text-blue-400"></i> 2. Describe New Background
              </label>
              <textarea 
                value={prompt}
                onChange={(e) => setPrompt(e.target.value)}
                placeholder="e.g., A futuristic cyberpunk city at neon-lit dusk with flying cars..."
                className="w-full bg-slate-800 border border-slate-700 rounded-xl p-4 text-slate-100 placeholder:text-slate-500 focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all min-h-[120px]"
              />

              <div className="mt-6">
                <button 
                  onClick={handleGenerate}
                  disabled={!sourceImage || !prompt.trim() || generation.isGenerating}
                  className={`w-full py-4 rounded-xl font-bold flex items-center justify-center gap-3 transition-all ${
                    !sourceImage || !prompt.trim() || generation.isGenerating
                      ? 'bg-slate-800 text-slate-500 cursor-not-allowed'
                      : 'bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-500 hover:to-indigo-500 text-white shadow-lg shadow-blue-500/20 active:scale-95'
                  }`}
                >
                  {generation.isGenerating ? (
                    <>
                      <i className="fa-solid fa-spinner fa-spin"></i>
                      Reimagining...
                    </>
                  ) : (
                    <>
                      <i className="fa-solid fa-wand-sparkles"></i>
                      Generate Masterpiece
                    </>
                  )}
                </button>
              </div>
            </div>
          </div>

          {/* Right Side: Result Area */}
          <div className="h-full">
            <div className="bg-slate-900/50 p-6 rounded-3xl border border-slate-800 shadow-xl h-full flex flex-col">
              <div className="flex items-center justify-between mb-6">
                <h3 className="text-sm font-medium text-slate-300 flex items-center gap-2">
                  <i className="fa-solid fa-star text-yellow-500"></i> Resulting Image
                </h3>
                {generation.resultUrl && (
                  <button 
                    onClick={() => {
                      const link = document.createElement('a');
                      link.href = generation.resultUrl!;
                      link.download = 'reimagined-background.png';
                      link.click();
                    }}
                    className="text-xs bg-slate-800 hover:bg-slate-700 px-3 py-1 rounded-full text-slate-300 transition-colors flex items-center gap-1"
                  >
                    <i className="fa-solid fa-download"></i> Save
                  </button>
                )}
              </div>

              <div className="flex-1 flex flex-col items-center justify-center border-2 border-dashed border-slate-800 rounded-2xl bg-slate-900/30 overflow-hidden relative">
                {generation.isGenerating ? (
                  <div className="text-center space-y-4 p-8">
                    <div className="w-12 h-12 border-4 border-blue-500/30 border-t-blue-500 rounded-full animate-spin mx-auto"></div>
                    <p className="text-slate-400 animate-pulse">Our AI is meticulously blending your subject into the new setting...</p>
                    <p className="text-xs text-slate-600">This usually takes about 10-15 seconds</p>
                  </div>
                ) : generation.resultUrl ? (
                  <img 
                    src={generation.resultUrl} 
                    alt="Result" 
                    className="w-full h-full object-contain transition-all duration-700 animate-in fade-in zoom-in"
                  />
                ) : generation.error ? (
                  <div className="text-center p-8">
                    <div className="w-16 h-16 bg-red-900/20 rounded-full flex items-center justify-center mx-auto mb-4">
                      <i className="fa-solid fa-triangle-exclamation text-2xl text-red-500"></i>
                    </div>
                    <p className="text-red-400 font-medium">Generation Error</p>
                    <p className="text-sm text-slate-500 mt-2">{generation.error}</p>
                    <button 
                      onClick={handleGenerate}
                      className="mt-6 text-blue-400 hover:text-blue-300 text-sm font-semibold underline underline-offset-4"
                    >
                      Try again
                    </button>
                  </div>
                ) : (
                  <div className="text-center p-8">
                    <i className="fa-solid fa-wand-magic-sparkles text-4xl text-slate-800 mb-4"></i>
                    <p className="text-slate-600">Generated result will appear here</p>
                  </div>
                )}
              </div>

              {generation.resultUrl && (
                <div className="mt-6 flex gap-4">
                  <button 
                    onClick={handleReset}
                    className="flex-1 py-3 bg-slate-800 hover:bg-slate-700 rounded-xl text-sm font-semibold transition-colors"
                  >
                    Clear All
                  </button>
                  <button 
                    onClick={handleGenerate}
                    className="flex-1 py-3 bg-blue-600 hover:bg-blue-500 rounded-xl text-sm font-semibold transition-colors"
                  >
                    Try New Background
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Feature Highlights */}
        <section className="mt-20 grid md:grid-cols-3 gap-8">
          <div className="p-6 bg-slate-900/30 rounded-2xl border border-slate-800">
            <i className="fa-solid fa-scissors text-blue-400 text-xl mb-4"></i>
            <h4 className="font-bold mb-2">Smart Extraction</h4>
            <p className="text-sm text-slate-500">Advanced edge detection ensures your subject is perfectly clipped from any complex background.</p>
          </div>
          <div className="p-6 bg-slate-900/30 rounded-2xl border border-slate-800">
            <i className="fa-solid fa-cloud-bolt text-indigo-400 text-xl mb-4"></i>
            <h4 className="font-bold mb-2">Seamless Blending</h4>
            <p className="text-sm text-slate-500">Gemini 3 Pro matches the lighting and color of the new background to the original subject.</p>
          </div>
          <div className="p-6 bg-slate-900/30 rounded-2xl border border-slate-800">
            <i className="fa-solid fa-shield-halved text-purple-400 text-xl mb-4"></i>
            <h4 className="font-bold mb-2">Pro Results</h4>
            <p className="text-sm text-slate-500">Get high-resolution, professional-grade image edits in seconds without complex software.</p>
          </div>
        </section>
      </main>

      {/* Footer */}
      <footer className="mt-20 border-t border-slate-900 py-12 text-center">
        <p className="text-slate-600 text-sm">
          Powered by Gemini 3 Pro Image &bull; Made for effortless creativity
        </p>
      </footer>
    </div>
  );
};

export default App;

