import { GoogleGenAI } from "@google/genai";

export const MODEL_NAME = 'gemini-3-pro-image-preview';

export async function editImageBackground(
  imageContent: string, 
  prompt: string,
  aspectRatio: "1:1" | "3:4" | "4:3" | "9:16" | "16:9" = "1:1"
): Promise<string> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Strengthened system instruction for high-fidelity preservation
  const systemInstruction = `You are a professional AI photo editor specializing in pixel-perfect subject preservation. 
  Your primary rule: DO NOT ALTER THE SUBJECT. The person, animal, or object from the original image must remain 100% identical in facial features, pose, clothing, and textures.
  Your task:
  1. Extract the main subject from the provided image with sharp, clean edges.
  2. Generate a new background based on the user's description.
  3. Seamlessly composite the original subject onto the new background.
  4. Adjust global lighting and shadows ONLY to ensure the subject feels physically present in the new scene, but do not change the subject's inherent characteristics.`;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: {
        parts: [
          {
            inlineData: {
              data: imageContent.split(',')[1],
              mimeType: 'image/png',
            },
          },
          {
            text: `[STRICT SUBJECT PRESERVATION MODE] 
            Keep the subject from this image exactly as they are. 
            Replace everything else (the background) with: ${prompt}. 
            The subject must not be redrawn or modified. Only the environment changes. 
            Ensure natural shadows where the subject meets the new ground.`,
          },
        ],
      },
      config: {
        systemInstruction,
        imageConfig: {
          aspectRatio,
          imageSize: "1K"
        }
      }
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }

    throw new Error("No image was generated by the model.");
  } catch (error: any) {
    if (error.message?.includes("Requested entity was not found")) {
      throw new Error("API_KEY_EXPIRED");
    }
    throw error;
  }
}

export async function fileToBase64(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = (error) => reject(error);
  });
}

