import { GoogleGenAI } from "@google/genai";

export const MODEL_NAME = 'gemini-3-pro-image-preview';

export type SupportedAspectRatio = "1:1" | "3:4" | "4:3" | "9:16" | "16:9";

export async function editImageBackground(
  imageContent: string, 
  prompt: string,
  aspectRatio: SupportedAspectRatio = "1:1"
): Promise<string> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Maximum strictness for subject preservation
  const systemInstruction = `You are a high-end visual effects compositor. 
  Your absolute priority is the STRICTURE PRESERVATION of the main subject in the foreground. 

  STEPS:
  1. Extract the main subject from the provided image with perfect edge detection (hair, transparent areas, etc.).
  2. DELETE the original background completely.
  3. GENERATE a new environment based on the user's description.
  4. PLACE the ORIGINAL subject back into this new environment.

  CONSTRAINTS:
  - DO NOT modify the subject's face, body, clothing, or pose. 
  - DO NOT 're-draw' the subject. The subject must be a pixel-for-pixel carryover from the source.
  - BLEND the subject by adding matching environmental lighting, bounce light, and contact shadows where they touch the new ground/objects.
  - The final output MUST maintain the high detail of the original subject.`;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: {
        parts: [
          {
            inlineData: {
              data: imageContent.split(',')[1],
              mimeType: 'image/png',
            },
          },
          {
            text: `[STRICT SUBJECT RETENTION MODE] 
            1. Remove current background.
            2. Add new background: ${prompt}.
            3. Subject must remain identical to source image. 
            4. Blend lighting seamlessly for a photorealistic result.`,
          },
        ],
      },
      config: {
        systemInstruction,
        imageConfig: {
          aspectRatio,
          imageSize: "4K" // Explicitly requested 4K output
        }
      }
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }

    throw new Error("No image was generated. The model might have filtered the content or failed to process the mask.");
  } catch (error: any) {
    if (error.message?.includes("Requested entity was not found")) {
      throw new Error("API_KEY_EXPIRED");
    }
    throw error;
  }
}

export async function fileToBase64(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = (error) => reject(error);
  });
}

/**
 * Maps an image's natural dimensions to the closest supported aspect ratio.
 */
export function getClosestAspectRatio(width: number, height: number): SupportedAspectRatio {
  const ratio = width / height;
  const supported = {
    "1:1": 1,
    "3:4": 3/4,
    "4:3": 4/3,
    "9:16": 9/16,
    "16:9": 16/9
  };

  let closest: SupportedAspectRatio = "1:1";
  let minDiff = Infinity;

  for (const [key, value] of Object.entries(supported)) {
    const diff = Math.abs(ratio - value);
    if (diff < minDiff) {
      minDiff = diff;
      closest = key as SupportedAspectRatio;
    }
  }

  return closest;
}

