                </div>
                <div className="flex items-center gap-3">
                   {generation.resultUrl && (
                      <button 
                        onClick={() => {
                          const link = document.createElement('a');
                          link.href = generation.resultUrl!;
                          link.download = 'composite-master-4k.png';
                          link.click();
                        }}
                        className="p-3 bg-white/5 hover:bg-white/10 rounded-2xl text-blue-400 transition-all"
                        title="Download 4K"
                      >
                        <i className="fa-solid fa-download"></i>
                      </button>
                   )}
                </div>
              </div>

              <div className="flex-1 flex items-center justify-center p-4">
                {generation.isGenerating ? (
                  <div className="text-center">
                    <div className="relative w-24 h-24 mx-auto mb-8">
                      <div className="absolute inset-0 border-4 border-blue-600/20 rounded-full"></div>
                      <div className="absolute inset-0 border-4 border-transparent border-t-blue-500 rounded-full animate-spin"></div>
                      <i className="fa-solid fa-microchip absolute inset-0 flex items-center justify-center text-blue-500 text-2xl"></i>
                    </div>
                    <h3 className="text-xl font-bold text-white mb-2">Surgical Background Extraction</h3>
                    <p className="text-slate-500 text-sm max-w-sm mx-auto">Locking subject identity and rendering new 4K environment.</p>
                  </div>
                ) : generation.resultUrl ? (
                  <div className="relative w-full h-full max-h-[700px] flex items-center justify-center rounded-3xl overflow-hidden shadow-2xl border border-white/10">
                    <div className="relative w-full h-full flex items-center justify-center bg-[#0a0a0a]">
                      {/* Before (Source) */}
                      <img 
                        src={sourceImage?.previewUrl} 
                        className="absolute w-full h-full object-contain pointer-events-none" 
                        alt="Before"
                      />

                      {/* After (Result) */}
                      <div 
                        className="absolute inset-0 overflow-hidden pointer-events-none select-none"
                        style={{ width: `${sliderPos}%` }}
                      >
                        <img 
                          src={generation.resultUrl} 
                          className="absolute w-full h-full object-contain pointer-events-none"
                          style={{ width: `${100 * (100/sliderPos)}%` }}
                          alt="After"
                        />
                        <div className="absolute top-4 left-4 bg-blue-600 px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-widest shadow-lg">New 4K Composite</div>
                      </div>

                      {/* Slider Control */}
                      <input 
                        type="range" 
                        min="0" 
                        max="100" 
                        value={sliderPos} 
                        onChange={(e) => setSliderPos(Number(e.target.value))}
                        className="absolute inset-0 w-full h-full opacity-0 cursor-ew-resize z-20"
                      />

                      {/* Handle Visual */}
                      <div 
                        className="absolute top-0 bottom-0 w-[2px] bg-white shadow-[0_0_10px_rgba(255,255,255,0.5)] z-10 pointer-events-none"
                        style={{ left: `${sliderPos}%` }}
                      >
                        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-10 h-10 bg-white rounded-full flex items-center justify-center text-slate-900 shadow-2xl">
                          <i className="fa-solid fa-arrows-left-right text-sm"></i>
                        </div>
                      </div>

                      <div className="absolute bottom-6 right-6 bg-black/60 backdrop-blur-md px-4 py-2 rounded-xl border border-white/5 text-[10px] text-slate-400 font-bold uppercase pointer-events-none">
                        Slide to verify identity retention
                      </div>
                    </div>
                  </div>
                ) : generation.error ? (
                  <div className="text-center p-12 bg-red-500/5 rounded-3xl border border-red-500/20">
                    <i className="fa-solid fa-bug text-3xl text-red-500 mb-6"></i>
                    <h3 className="text-xl font-bold text-red-400 mb-2">Composite Failed</h3>
                    <p className="text-slate-500 text-sm mb-8">{generation.error}</p>
                    <button onClick={handleGenerate} className="px-8 py-3 bg-red-500/10 hover:bg-red-500/20 text-red-400 rounded-xl font-bold transition-all">Retry Render</button>
                  </div>
                ) : (
                  <div className="text-center group">
                    <div className="w-32 h-32 bg-slate-800/50 rounded-full flex items-center justify-center mx-auto mb-8 border border-white/5 group-hover:scale-105 transition-transform duration-500">
                      <i className="fa-solid fa-wand-magic-sparkles text-4xl text-slate-700 group-hover:text-blue-500/50 transition-colors"></i>
                    </div>
                    <p className="text-slate-500 font-medium">Ready for Surgical 4K Composite</p>
                    <p className="text-xs text-slate-700 mt-2 tracking-widest uppercase">Detected Aspect Ratio: {aspectRatio}</p>
                  </div>
                )}
              </div>
            </div>

            {generation.resultUrl && (
              <div className="mt-8 flex items-center justify-center gap-6">
                <button onClick={handleReset} className="px-8 py-3 bg-slate-900 hover:bg-slate-800 text-slate-300 rounded-2xl text-sm font-bold transition-all border border-white/5">
                  Discard & Reset
                </button>
                <div className="h-4 w-[1px] bg-white/10"></div>
                <p className="text-xs text-slate-500">Output rendered in 4K resolution.</p>
              </div>
            )}
          </div>

        </div>

        {/* Feature Grid */}
        <section className="mt-24 grid md:grid-cols-3 gap-8 pb-12">
          <div className="p-8 bg-slate-900/30 rounded-3xl border border-white/5">
            <div className="w-12 h-12 bg-blue-600/10 rounded-2xl flex items-center justify-center mb-6">
              <i className="fa-solid fa-expand text-blue-500"></i>
            </div>
            <h4 className="text-lg font-bold mb-3">4K Ultra HD</h4>
            <p className="text-sm text-slate-500 leading-relaxed">Gemini 3 Pro renders your reimagined world in stunning 4K detail, perfect for high-resolution displays and print.</p>
          </div>
          <div className="p-8 bg-slate-900/30 rounded-3xl border border-white/5">
            <div className="w-12 h-12 bg-indigo-600/10 rounded-2xl flex items-center justify-center mb-6">
              <i className="fa-solid fa-dna text-indigo-500"></i>
            </div>
            <h4 className="text-lg font-bold mb-3">Surgical Precision</h4>
            <p className="text-sm text-slate-500 leading-relaxed">The engine locks original pixel data, preventing any modification to the subject's face, features, or unique textures.</p>
          </div>
          <div className="p-8 bg-slate-900/30 rounded-3xl border border-white/5">
            <div className="w-12 h-12 bg-purple-600/10 rounded-2xl flex items-center justify-center mb-6">
              <i className="fa-solid fa-image text-purple-500"></i>
            </div>
            <h4 className="text-lg font-bold mb-3">Ratio Matching</h4>
            <p className="text-sm text-slate-500 leading-relaxed">We automatically detect your source image's aspect ratio and ensure the generated masterpiece matches it perfectly.</p>
          </div>
        </section>
      </main>

      <footer className="mt-12 border-t border-white/5 py-12 text-center">
        <div className="flex items-center justify-center gap-2 mb-4">
          <div className="w-6 h-6 bg-blue-600 rounded flex items-center justify-center">
            <i className="fa-solid fa-layer-group text-[10px] text-white"></i>
          </div>
          <span className="text-sm font-bold tracking-tight">Nano Banana <span className="text-blue-500">Pro</span></span>
        </div>
        <p className="text-slate-600 text-xs font-bold uppercase tracking-[0.2em]">
          Powered by Gemini 3 Pro &bull; Surgical 4K Edition
        </p>
      </footer>
    </div>
  );
};

export default App;

export interface GenerationState {
  isGenerating: boolean;
  error: string | null;
  resultUrl: string | null;
}

export interface ImagePreview {
  file: File;
  previewUrl: string;
}

declare global {
  /**
   * Fix: Define the AIStudio interface in the global scope to ensure it matches
   * the environment's expectations. TypeScript will merge this with any
   * existing global AIStudio interface.
   */
  interface AIStudio {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  }

  /**
   * Fix: Removed 'readonly' modifier to ensure this declaration matches the existing
   * definition of 'aistudio' in the global environment, resolving the 
   * "All declarations of 'aistudio' must have identical modifiers" error.
   */
  interface Window {
    aistudio: AIStudio;
  }
}

export type ProcessStatus = 'idle' | 'processing' | 'completed' | 'error';

export interface ImageItem {
  id: string;
  file: File;
  previewUrl: string;
  resultUrl: string | null;
  aspectRatio: "1:1" | "3:4" | "4:3" | "9:16" | "16:9";
  status: ProcessStatus;
  error?: string | null;
}

export interface GenerationState {
  isGenerating: boolean;
  error: string | null;
}

export interface ImagePreview {
  file: File;
  previewUrl: string;
}

declare global {
  interface AIStudio {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  }

  interface Window {
    aistudio: AIStudio;
  }
}

import React, { useState, useEffect, useRef } from 'react';
import ApiKeyGate from './components/ApiKeyGate';
import { editImageBackground, fileToBase64, getClosestAspectRatio } from './services/geminiService';
import { ImageItem, ProcessStatus } from './types';

const App: React.FC = () => {
  const [hasKey, setHasKey] = useState<boolean | null>(null);
  const [images, setImages] = useState<ImageItem[]>([]);
  const [activeId, setActiveId] = useState<string | null>(null);
  const [prompt, setPrompt] = useState<string>('');
  const [sliderPos, setSliderPos] = useState<number>(50);
  const [isBulkProcessing, setIsBulkProcessing] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const checkKey = async () => {
      const selected = await window.aistudio.hasSelectedApiKey();
      setHasKey(selected);
    };
    checkKey();
  }, []);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || []);
    if (files.length === 0) return;

    const newItems: ImageItem[] = await Promise.all(
      files.map(async (file) => {
        const url = URL.createObjectURL(file);

        // Detect aspect ratio
        const aspectRatio = await new Promise<any>((resolve) => {
          const img = new Image();
          img.onload = () => resolve(getClosestAspectRatio(img.width, img.height));
          img.src = url;
        });

        return {
          id: Math.random().toString(36).substring(7),
          file,
          previewUrl: url,
          resultUrl: null,
          aspectRatio,
          status: 'idle' as const,
        };
      })
    );

    setImages(prev => [...prev, ...newItems]);
    if (!activeId && newItems.length > 0) {
      setActiveId(newItems[0].id);
    }
  };

  const processSingleImage = async (item: ImageItem, currentPrompt: string) => {
    setImages(prev => prev.map(img => img.id === item.id ? { ...img, status: 'processing', error: null } : img));

    try {
      const base64 = await fileToBase64(item.file);
      const result = await editImageBackground(base64, currentPrompt, item.aspectRatio);
      setImages(prev => prev.map(img => img.id === item.id ? { ...img, status: 'completed', resultUrl: result, error: null } : img));
    } catch (err: any) {
      const isAuthError = err.message === "API_KEY_EXPIRED";
      if (isAuthError) setHasKey(false);

      setImages(prev => prev.map(img => img.id === item.id ? { 
        ...img, 
        status: 'error', 
        error: isAuthError ? "API Key Expired" : (err.message || "Processing failed") 
      } : img));
      throw err; // Stop bulk process if error occurs
    }
  };

  const handleBulkGenerate = async () => {
    if (images.length === 0 || !prompt.trim() || isBulkProcessing) return;

    setIsBulkProcessing(true);
    const pendingImages = images.filter(img => img.status !== 'completed');

    for (const item of pendingImages) {
      try {
        await processSingleImage(item, prompt);
      } catch (e) {
        console.error("Stopping bulk process due to error", e);
        break; 
      }
    }
    setIsBulkProcessing(false);
  };

  const handleRemoveImage = (id: string) => {
    setImages(prev => {
      const filtered = prev.filter(img => img.id !== id);
      if (activeId === id) {
        setActiveId(filtered.length > 0 ? filtered[0].id : null);
      }
      return filtered;
    });
  };

  const activeImage = images.find(img => img.id === activeId);

  if (hasKey === null) return <div className="min-h-screen bg-slate-950 flex items-center justify-center"><i className="fa-solid fa-spinner fa-spin text-4xl text-blue-500"></i></div>;
  if (hasKey === false) return <div className="min-h-screen bg-slate-950 pt-20"><ApiKeyGate onSuccess={() => setHasKey(true)} /></div>;

  return (
    <div className="min-h-screen bg-[#020617] text-slate-100 pb-20 selection:bg-blue-500/30">
      {/* Navbar */}
      <nav className="border-b border-white/5 bg-[#020617]/80 backdrop-blur-xl sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-6 h-20 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center shadow-lg shadow-blue-600/20">
              <i className="fa-solid fa-layer-group text-white text-lg"></i>
            </div>
            <div>
              <h1 className="text-xl font-bold tracking-tight leading-none">Nano Banana <span className="text-blue-500">Pro</span></h1>
              <span className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">Surgical Bulk 4K Composite</span>
            </div>
          </div>
          <button 
            onClick={() => window.aistudio.openSelectKey()}
            className="text-xs font-semibold px-4 py-2 rounded-full border border-white/10 hover:bg-white/5 transition-all flex items-center gap-2"
          >
            <i className="fa-solid fa-key text-blue-400"></i> Change API Key
          </button>
        </div>
      </nav>

      <main className="max-w-[1600px] mx-auto px-6 mt-8">
        <div className="grid grid-cols-1 xl:grid-cols-12 gap-8">

          {/* Left Panel: Sidebar / Image Queue */}
          <div className="xl:col-span-3 space-y-6">
            <section className="bg-slate-900/50 border border-white/5 rounded-3xl p-6 backdrop-blur-sm shadow-2xl h-[calc(100vh-12rem)] flex flex-col">
              <div className="flex items-center justify-between mb-6">
                <h2 className="text-sm font-bold uppercase tracking-widest text-slate-400">Image Queue</h2>
                <span className="bg-blue-500/10 text-blue-400 text-[10px] font-bold px-2 py-1 rounded-full">{images.length} Loaded</span>
              </div>

              <div className="flex-1 overflow-y-auto space-y-3 pr-2 scrollbar-thin scrollbar-thumb-slate-700">
                {images.map((img) => (
                  <div 
                    key={img.id}
                    onClick={() => setActiveId(img.id)}
                    className={`relative group p-2 rounded-2xl border transition-all cursor-pointer ${
                      activeId === img.id ? 'bg-blue-600/10 border-blue-500/50' : 'bg-black/20 border-white/5 hover:border-white/10'
                    }`}
                  >
                    <div className="flex items-center gap-3">
                      <div className="w-16 h-16 rounded-xl overflow-hidden bg-slate-800 flex-shrink-0">
                        <img src={img.previewUrl} className="w-full h-full object-cover" />
                      </div>
                      <div className="flex-1 min-w-0">
                        <p className="text-[10px] font-bold text-slate-500 uppercase tracking-tighter truncate">{img.file.name}</p>
                        <div className="flex items-center gap-2 mt-1">
                          {img.status === 'processing' && <i className="fa-solid fa-spinner fa-spin text-blue-400 text-[10px]"></i>}
                          {img.status === 'completed' && <i className="fa-solid fa-circle-check text-green-500 text-[10px]"></i>}
                          {img.status === 'error' && <i className="fa-solid fa-triangle-exclamation text-red-500 text-[10px]"></i>}
                          <span className="text-[10px] font-bold uppercase tracking-widest text-slate-300">
                            {img.status}
                          </span>
                        </div>
                      </div>
                    </div>
                    <button 
                      onClick={(e) => { e.stopPropagation(); handleRemoveImage(img.id); }}
                      className="absolute -top-1 -right-1 w-6 h-6 bg-red-500/80 hover:bg-red-500 text-white rounded-full opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center text-[10px]"
                    >
                      <i className="fa-solid fa-xmark"></i>
                    </button>
                  </div>
                ))}

                <button 
                  onClick={() => fileInputRef.current?.click()}
                  className="w-full border-2 border-dashed border-white/10 rounded-2xl py-8 flex flex-col items-center justify-center gap-2 hover:border-blue-500/30 hover:bg-blue-500/5 transition-all"
                >
                  <i className="fa-solid fa-plus text-slate-600"></i>
                  <span className="text-[10px] font-bold uppercase tracking-widest text-slate-500">Add More Images</span>
                </button>
                <input type="file" multiple ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileChange} />
              </div>
            </section>
          </div>

          {/* Center Panel: Main Viewport */}
          <div className="xl:col-span-6 flex flex-col gap-6">
            <div className="bg-slate-900/40 border border-white/5 rounded-[40px] p-4 flex-1 flex flex-col relative overflow-hidden shadow-inner min-h-[600px]">
              <div className="flex items-center justify-between px-6 py-4 border-b border-white/5 mb-4">
                <div className="flex items-center gap-3">
                  <div className={`w-2 h-2 rounded-full ${activeImage?.status === 'processing' ? 'bg-blue-500 animate-pulse' : activeImage?.status === 'completed' ? 'bg-green-500' : 'bg-slate-500'}`}></div>
                  <span className="text-xs font-bold text-slate-400 tracking-widest uppercase">
                    {activeImage ? activeImage.file.name : "Viewport Ready"}
                  </span>
                </div>
                {activeImage?.resultUrl && (
                  <button 
                    onClick={() => {
                      const link = document.createElement('a');
                      link.href = activeImage.resultUrl!;
                      link.download = `composite-${activeImage.id}.png`;
                      link.click();
                    }}
                    className="p-3 bg-white/5 hover:bg-white/10 rounded-2xl text-blue-400 transition-all flex items-center gap-2"
                  >
                    <i className="fa-solid fa-download"></i>
                    <span className="text-[10px] font-bold uppercase">Download 4K</span>
                  </button>
                )}
              </div>

              <div className="flex-1 flex items-center justify-center p-4">
                {!activeImage ? (
                  <div className="text-center group">
                    <div className="w-32 h-32 bg-slate-800/50 rounded-full flex items-center justify-center mx-auto mb-8 border border-white/5 group-hover:scale-105 transition-transform duration-500">
                      <i className="fa-solid fa-images text-4xl text-slate-700 group-hover:text-blue-500/50 transition-colors"></i>
                    </div>
                    <p className="text-slate-500 font-medium">Upload multiple subjects to start</p>
                  </div>
                ) : activeImage.status === 'processing' ? (
                  <div className="text-center">
                    <div className="relative w-24 h-24 mx-auto mb-8">
                      <div className="absolute inset-0 border-4 border-blue-600/20 rounded-full"></div>
                      <div className="absolute inset-0 border-4 border-transparent border-t-blue-500 rounded-full animate-spin"></div>
                      <i className="fa-solid fa-microchip absolute inset-0 flex items-center justify-center text-blue-500 text-2xl"></i>
                    </div>
                    <h3 className="text-xl font-bold text-white mb-2">Rendering 4K Canvas</h3>
                    <p className="text-slate-500 text-sm">Processing "{activeImage.file.name}"...</p>
                  </div>
                ) : activeImage.resultUrl ? (
                  <div className="relative w-full h-full flex items-center justify-center rounded-3xl overflow-hidden shadow-2xl border border-white/10 bg-[#0a0a0a]">
                    <img src={activeImage.previewUrl} className="absolute w-full h-full object-contain pointer-events-none" />
                    <div 
                      className="absolute inset-0 overflow-hidden pointer-events-none select-none"
                      style={{ width: `${sliderPos}%` }}
                    >
                      <img 
                        src={activeImage.resultUrl} 
                        className="absolute w-full h-full object-contain pointer-events-none"
                        style={{ width: `${100 * (100/sliderPos)}%` }}
                      />
                    </div>
                    <input type="range" min="0" max="100" value={sliderPos} onChange={(e) => setSliderPos(Number(e.target.value))} className="absolute inset-0 w-full h-full opacity-0 cursor-ew-resize z-20" />
                    <div className="absolute top-0 bottom-0 w-[2px] bg-white shadow-[0_0_10px_rgba(255,255,255,0.5)] z-10 pointer-events-none" style={{ left: `${sliderPos}%` }}>
                      <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-10 h-10 bg-white rounded-full flex items-center justify-center text-slate-900 shadow-2xl"><i className="fa-solid fa-arrows-left-right text-sm"></i></div>
                    </div>
                  </div>
                ) : (
                  <div className="relative group w-full h-full flex items-center justify-center">
                    <img src={activeImage.previewUrl} className="w-full h-full object-contain rounded-3xl opacity-50" />
                    <div className="absolute inset-0 flex items-center justify-center">
                       <span className="px-6 py-3 bg-black/40 backdrop-blur-md rounded-2xl text-slate-300 font-bold border border-white/5">Preview Mode - Awaiting Generation</span>
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>

          {/* Right Panel: Controls */}
          <div className="xl:col-span-3 space-y-6">
            <section className="bg-slate-900/50 border border-white/5 rounded-3xl p-8 backdrop-blur-sm shadow-2xl">
              <h2 className="text-lg font-bold mb-6 flex items-center gap-3">
                <span className="w-6 h-6 rounded-full bg-blue-500/20 flex items-center justify-center text-[10px] text-blue-400">Global</span>
                Background
              </h2>
              <textarea 
                value={prompt}
                onChange={(e) => setPrompt(e.target.value)}
                placeholder="Describe the shared background... e.g. A hyper-realistic luxury studio with soft rim lighting and a minimalist concrete floor."
                className="w-full bg-black/40 border border-white/5 rounded-2xl p-5 text-sm text-slate-100 placeholder:text-slate-600 focus:outline-none focus:ring-2 focus:ring-blue-500/50 transition-all min-h-[160px] resize-none"
              />

              <div className="mt-8 space-y-4">
                <button 
                  onClick={handleBulkGenerate}
                  disabled={images.length === 0 || !prompt.trim() || isBulkProcessing}
                  className={`w-full py-4 rounded-2xl font-bold flex flex-col items-center justify-center gap-1 transition-all ${
                    images.length === 0 || !prompt.trim() || isBulkProcessing
                      ? 'bg-slate-800 text-slate-600 cursor-not-allowed opacity-50'
                      : 'bg-blue-600 hover:bg-blue-500 text-white shadow-lg shadow-blue-600/25 active:scale-95'
                  }`}
                >
                  <div className="flex items-center gap-2">
                    {isBulkProcessing ? (
                      <><i className="fa-solid fa-circle-notch fa-spin"></i> Processing Bulk</>
                    ) : (
                      <><i className="fa-solid fa-wand-sparkles"></i> Render All Images</>
                    )}
                  </div>
                  <span className="text-[10px] font-bold opacity-60 uppercase tracking-widest">
                    {images.filter(i => i.status !== 'completed').length} Pending
                  </span>
                </button>

                <button 
                  onClick={() => setImages([])}
                  disabled={images.length === 0 || isBulkProcessing}
                  className="w-full py-3 bg-slate-900/80 hover:bg-slate-800 text-slate-400 text-xs font-bold rounded-2xl border border-white/5 transition-all uppercase tracking-widest"
                >
                  Clear All
                </button>
              </div>

              {/* Progress Summary */}
              {images.length > 0 && (
                <div className="mt-8 p-4 bg-black/30 rounded-2xl border border-white/5 space-y-3">
                  <div className="flex justify-between text-[10px] font-bold text-slate-500 uppercase">
                    <span>Progress</span>
                    <span>{images.filter(i => i.status === 'completed').length} / {images.length}</span>
                  </div>
                  <div className="w-full h-1.5 bg-slate-800 rounded-full overflow-hidden">
                    <div 
                      className="h-full bg-blue-500 transition-all duration-500"
                      style={{ width: `${(images.filter(i => i.status === 'completed').length / images.length) * 100}%` }}
                    />
                  </div>
                </div>
              )}
            </section>

            {/* Quick Tips */}
