import { GoogleGenAI } from "@google/genai";

export const MODEL_NAME = 'gemini-3-pro-image-preview';

export type SupportedAspectRatio = "1:1" | "3:4" | "4:3" | "9:16" | "16:9";

export async function editImageBackground(
  imageContent: string, 
  prompt: string,
  aspectRatio: SupportedAspectRatio = "1:1",
  referenceImageContent?: string | null // Optional master reference for consistency
): Promise<string> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Refined system instruction for consistency
  const systemInstruction = `You are a high-end visual effects compositor specializing in consistent environment matching.

  TASK:
  1. If a REFERENCE IMAGE is provided, your job is to extract the EXACT environment (lighting, objects, floor, background) from that image.
  2. Take the CURRENT SUBJECT from the source image and place them into that EXACT environment.
  3. Ensure the subject's lighting, shadows, and contact points match the environment from the reference image perfectly.
  4. If NO reference image is provided, generate a new environment based on the prompt while preserving the subject exactly.

  CONSTRAINTS:
  - Subject identity must be a pixel-for-pixel carryover from the source.
  - Do not redraw or reimagining the subject.
  - The final output MUST maintain 4K detail.`;

  const contents: any = {
    parts: [
      {
        inlineData: {
          data: imageContent.split(',')[1],
          mimeType: 'image/png',
        },
      }
    ]
  };

  // Add reference image if available
  if (referenceImageContent) {
    contents.parts.push({
      inlineData: {
        data: referenceImageContent.split(',')[1],
        mimeType: 'image/png',
      },
    });

    contents.parts.push({
      text: `[CONSISTENCY MODE ACTIVE] 
      - SOURCE IMAGE: The first image provided is the subject.
      - REFERENCE IMAGE: The second image provided is the TARGET ENVIRONMENT.
      - TASK: Place the subject from the source image into the environment of the reference image.
      - ENVIRONMENT DESCRIPTION: ${prompt}. Match the reference image's style, colors, and lighting exactly.`,
    });
  } else {
    contents.parts.push({
      text: `[STRICT SUBJECT RETENTION MODE] 
      - TASK: Remove current background and add new background: ${prompt}.
      - Subject must remain identical to source image. 
      - Output 4K resolution.`,
    });
  }

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents,
      config: {
        systemInstruction,
        imageConfig: {
          aspectRatio,
          imageSize: "4K"
        }
      }
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }

    throw new Error("No image was generated. The model might have filtered the content or failed to process the mask.");
  } catch (error: any) {
    if (error.message?.includes("Requested entity was not found")) {
      throw new Error("API_KEY_EXPIRED");
    }
    throw error;
  }
}

export async function fileToBase64(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = (error) => reject(error);
  });
}

export function getClosestAspectRatio(width: number, height: number): SupportedAspectRatio {
  const ratio = width / height;
  const supported = {
    "1:1": 1,
    "3:4": 3/4,
    "4:3": 4/3,
    "9:16": 9/16,
    "16:9": 16/9
  };

  let closest: SupportedAspectRatio = "1:1";
  let minDiff = Infinity;

  for (const [key, value] of Object.entries(supported)) {
    const diff = Math.abs(ratio - value);
    if (diff < minDiff) {
      minDiff = diff;
      closest = key as SupportedAspectRatio;
    }
  }

  return closest;
}

