              <div className="flex items-center justify-between mb-6">
                <h2 className="text-sm font-bold uppercase tracking-widest text-slate-400">Image Queue</h2>
                <span className="bg-blue-500/10 text-blue-400 text-[10px] font-bold px-2 py-1 rounded-full">{images.length} Loaded</span>
              </div>

              <div className="flex-1 overflow-y-auto space-y-3 pr-2 scrollbar-thin scrollbar-thumb-slate-700">
                {images.map((img) => (
                  <div 
                    key={img.id}
                    onClick={() => setActiveId(img.id)}
                    className={`relative group p-2 rounded-2xl border transition-all cursor-pointer ${
                      activeId === img.id ? 'bg-blue-600/10 border-blue-500/50' : 'bg-black/20 border-white/5 hover:border-white/10'
                    }`}
                  >
                    <div className="flex items-center gap-3">
                      <div className="w-16 h-16 rounded-xl overflow-hidden bg-slate-800 flex-shrink-0 relative">
                        <img src={img.previewUrl} className="w-full h-full object-cover" />
                        {img.id === firstCompletedId && lockConsistency && (
                           <div className="absolute inset-0 bg-blue-600/40 flex items-center justify-center">
                              <i className="fa-solid fa-crown text-white text-[10px]"></i>
                           </div>
                        )}
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-1">
                          <p className="text-[10px] font-bold text-slate-500 uppercase tracking-tighter truncate">{img.file.name}</p>
                          {img.id === firstCompletedId && lockConsistency && (
                            <span className="text-[8px] bg-blue-500 text-white px-1 rounded">MASTER</span>
                          )}
                        </div>
                        <div className="flex items-center gap-2 mt-1">
                          {img.status === 'processing' && <i className="fa-solid fa-spinner fa-spin text-blue-400 text-[10px]"></i>}
