                    <img src={activeImage.previewUrl} className="absolute w-full h-full object-contain pointer-events-none" />
                    <div 
                      className="absolute inset-0 overflow-hidden pointer-events-none select-none"
                      style={{ width: `${sliderPos}%` }}
