import { GoogleGenAI } from "@google/genai";

export const MODEL_NAME = 'gemini-3-pro-image-preview';

export type SupportedAspectRatio = "1:1" | "3:4" | "4:3" | "9:16" | "16:9";

export async function editImageBackground(
  imageContent: string, 
  prompt: string,
  aspectRatio: SupportedAspectRatio = "1:1",
  referenceImageContent?: string | null 
): Promise<string> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const systemInstruction = `You are an elite VFX compositor and architectural visualizer. 
  Your primary goal is to re-render the background of an image while maintaining 100% spatial and structural fidelity.

  STRICT RULES:
  1. PERSPECTIVE & ANGLE: Do not change the camera angle, focal length, or perspective.
  2. STRUCTURE & FURNITURE: If the original image contains furniture, walls, or architectural features, you must KEEP their exact positions and silhouettes. You may update their materials, textures, and lighting to match the new theme, but do NOT remove them or add new unrelated furniture that changes the room's layout.
  3. SUBJECT FIDELITY: The foreground subject must remain a pixel-for-pixel match to the source. Do not redraw the subject.
  4. NO EXTENSION: Do not extend the scene beyond its original boundaries or introduce "AI filler" that breaks the original composition.
  5. BLENDING: Add realistic contact shadows and environmental reflections on the subject that match the new background lighting.`;

  const contents: any = {
    parts: [
      {
        inlineData: {
          data: imageContent.split(',')[1],
          mimeType: 'image/png',
        },
      }
    ]
  };

  if (referenceImageContent) {
    contents.parts.push({
      inlineData: {
        data: referenceImageContent.split(',')[1],
        mimeType: 'image/png',
      },
    });

    contents.parts.push({
      text: `[STRUCTURAL CONSISTENCY MODE] 
      - SUBJECT: From Source Image.
      - ENVIRONMENT LAYOUT: Keep the exact furniture positions and room structure from the Source Image.
      - ENVIRONMENT STYLE: Match the materials, lighting, and textures found in the Reference Image.
      - THEME: ${prompt}.`,
    });
  } else {
    contents.parts.push({
      text: `[SPATIAL LOCK MODE] 
      - TASK: Re-imagine the background as: ${prompt}.
      - IMPORTANT: Keep all furniture, structural elements, and the camera angle identical to the original image. Only change the style, lighting, and materials of these elements.
      - Output 4K resolution.`,
    });
  }

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents,
      config: {
        systemInstruction,
        imageConfig: {
          aspectRatio,
          imageSize: "4K"
        }
      }
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }

    throw new Error("No image was generated. Check safety filters or try a different description.");
  } catch (error: any) {
    if (error.message?.includes("Requested entity was not found")) {
      throw new Error("API_KEY_EXPIRED");
    }
    throw error;
  }
}

export async function fileToBase64(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = (error) => reject(error);
  });
}

export function getClosestAspectRatio(width: number, height: number): SupportedAspectRatio {
  const ratio = width / height;
  const supported = {
    "1:1": 1,
    "3:4": 3/4,
    "4:3": 4/3,
    "9:16": 9/16,
    "16:9": 16/9
  };

  let closest: SupportedAspectRatio = "1:1";
  let minDiff = Infinity;

  for (const [key, value] of Object.entries(supported)) {
    const diff = Math.abs(ratio - value);
    if (diff < minDiff) {
      minDiff = diff;
      closest = key as SupportedAspectRatio;
    }
  }

  return closest;
}

import React, { useState, useEffect, useRef } from 'react';
import ApiKeyGate from './components/ApiKeyGate';
import { editImageBackground, fileToBase64, getClosestAspectRatio, SupportedAspectRatio } from './services/geminiService';
import { ImageItem, ProcessStatus } from './types';

const App: React.FC = () => {
  const [hasKey, setHasKey] = useState<boolean | null>(null);
  const [images, setImages] = useState<ImageItem[]>([]);
  const [activeId, setActiveId] = useState<string | null>(null);
  const [prompt, setPrompt] = useState<string>('');
  const [sliderPos, setSliderPos] = useState<number>(50);
  const [isBulkProcessing, setIsBulkProcessing] = useState(false);
  const [lockConsistency, setLockConsistency] = useState(true);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const checkKey = async () => {
      const selected = await window.aistudio.hasSelectedApiKey();
      setHasKey(selected);
    };
    checkKey();
  }, []);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || []) as File[];
    if (files.length === 0) return;

    const newItems: ImageItem[] = await Promise.all(
      files.map(async (file) => {
        const url = URL.createObjectURL(file);
        const aspectRatio = await new Promise<SupportedAspectRatio>((resolve) => {
          const img = new Image();
          img.onload = () => resolve(getClosestAspectRatio(img.width, img.height));
          img.src = url;
        });

        return {
          id: Math.random().toString(36).substring(7),
          file,
          previewUrl: url,
          resultUrl: null,
          aspectRatio,
          status: 'idle' as const,
        };
      })
    );

    setImages(prev => [...prev, ...newItems]);
    if (!activeId && newItems.length > 0) {
      setActiveId(newItems[0].id);
    }
  };

  const processSingleImage = async (item: ImageItem, currentPrompt: string, referenceUrl?: string | null) => {
    setImages(prev => prev.map(img => img.id === item.id ? { ...img, status: 'processing', error: null } : img));

    try {
      const base64 = await fileToBase64(item.file);
      const result = await editImageBackground(base64, currentPrompt, item.aspectRatio, referenceUrl);
      setImages(prev => prev.map(img => img.id === item.id ? { ...img, status: 'completed', resultUrl: result, error: null } : img));
      return result;
    } catch (err: any) {
      const isAuthError = err.message === "API_KEY_EXPIRED";
      if (isAuthError) setHasKey(false);

      setImages(prev => prev.map(img => img.id === item.id ? { 
        ...img, 
        status: 'error', 
        error: isAuthError ? "API Key Expired" : (err.message || "Processing failed") 
      } : img));
      throw err;
    }
  };

  const handleBulkGenerate = async () => {
    if (images.length === 0 || !prompt.trim() || isBulkProcessing) return;

    setIsBulkProcessing(true);
    const pendingImages = images.filter(img => img.status !== 'completed');

    let masterReferenceUrl: string | null = null;
    const existingMaster = images.find(img => img.status === 'completed' && img.resultUrl);
    if (lockConsistency && existingMaster) {
      masterReferenceUrl = existingMaster.resultUrl;
    }

    for (const item of pendingImages) {
      try {
        const resultUrl = await processSingleImage(item, prompt, masterReferenceUrl);
        if (lockConsistency && !masterReferenceUrl) {
          masterReferenceUrl = resultUrl;
        }
      } catch (e) {
        console.error("Stopping bulk process due to error", e);
        break; 
      }
    }
    setIsBulkProcessing(false);
  };

  const handleDownloadAll = () => {
    const completed = images.filter(img => img.resultUrl);
    if (completed.length === 0) return;

    completed.forEach((img, index) => {
      // Small timeout to prevent browser from blocking multiple simultaneous downloads
      setTimeout(() => {
        const link = document.createElement('a');
        link.href = img.resultUrl!;
        link.download = `composite-${img.id}.png`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
      }, index * 250);
    });
  };

  const handleRemoveImage = (id: string) => {
    setImages(prev => {
      const filtered = prev.filter(img => img.id !== id);
      if (activeId === id) {
        setActiveId(filtered.length > 0 ? filtered[0].id : null);
      }
      return filtered;
    });
  };

  const activeImage = images.find(img => img.id === activeId);
  const firstCompletedId = images.find(img => img.status === 'completed')?.id;
  const completedCount = images.filter(img => img.status === 'completed').length;

  if (hasKey === null) return <div className="min-h-screen bg-slate-950 flex items-center justify-center"><i className="fa-solid fa-spinner fa-spin text-4xl text-blue-500"></i></div>;
  if (hasKey === false) return <div className="min-h-screen bg-slate-950 pt-20"><ApiKeyGate onSuccess={() => setHasKey(true)} /></div>;

