import { GoogleGenAI } from "@google/genai";

export const MODEL_NAME = 'gemini-3-pro-image-preview';

export type SupportedAspectRatio = "1:1" | "3:4" | "4:3" | "9:16" | "16:9";

export async function editImageBackground(
  imageContent: string, 
  prompt: string,
  aspectRatio: SupportedAspectRatio = "1:1",
  referenceImageContent?: string | null 
): Promise<string> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const systemInstruction = `You are a surgical VFX compositor and architectural re-visualization specialist. 
  Your mission is to RE-MATERIALIZE the background of the source image while keeping the 3D geometry and furniture layout ABSOLUTELY FIXED.

  CRITICAL CONSTRAINTS:
  1. STRUCTURAL LOCK: Do not move, add, or remove any furniture, walls, windows, or architectural elements. If there is a chair, it must stay in the same place. If there is a desk, it must stay in the same place. Only change its material and lighting.
  2. NO SCENE EXTENSION: Do not "fill in" the background with new objects. Do not expand the field of view.
  3. GEOMETRY PRESERVATION: Treat the original background as a rigid 3D mesh. You are only allowed to swap the 'textures' and 'lighting' of that mesh. 
  4. CAMERA PERSPECTIVE: Maintain the exact camera angle, height, and focal length. 
  5. SUBJECT FIDELITY: The foreground person or subject must remain exactly as they appear in the source image, with no changes to their face, clothes, or pose.
  6. LIGHTING COHERENCE: Calculate contact shadows and ambient occlusion between the existing furniture and the subject based on the new lighting theme.`;

  const contents: any = {
    parts: [
      {
        inlineData: {
          data: imageContent.split(',')[1],
          mimeType: 'image/png',
        },
      }
    ]
  };

  if (referenceImageContent) {
    contents.parts.push({
      inlineData: {
        data: referenceImageContent.split(',')[1],
        mimeType: 'image/png',
      },
    });

    contents.parts.push({
      text: `[STRICT GEOMETRY TRANSFER] 
      - SUBJECT: From the Source Image.
      - SCENE LAYOUT: MUST MATCH the furniture and room structure of the Source Image exactly.
      - ENVIRONMENT STYLE: Extract the lighting, colors, and material finishes from the Reference Image and apply them to the Source Image's existing structure.
      - THEME: ${prompt}.`,
    });
  } else {
    contents.parts.push({
      text: `[SURFACE RE-MATERIALIZATION] 
      - TASK: Change the style of the existing background to: ${prompt}.
      - IMPORTANT: All furniture and walls must remain in their original positions. Do not add new furniture. 
      - Output 4K resolution with high structural fidelity.`,
    });
  }

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents,
      config: {
        systemInstruction,
        imageConfig: {
          aspectRatio,
          imageSize: "4K"
        }
      }
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }

    throw new Error("No image was generated. Check safety filters or try a different description.");
  } catch (error: any) {
    if (error.message?.includes("Requested entity was not found")) {
      throw new Error("API_KEY_EXPIRED");
    }
    throw error;
  }
}

export async function fileToBase64(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = (error) => reject(error);
  });
}

export function getClosestAspectRatio(width: number, height: number): SupportedAspectRatio {
  const ratio = width / height;
  const supported = {
    "1:1": 1,
    "3:4": 3/4,
    "4:3": 4/3,
    "9:16": 9/16,
    "16:9": 16/9
  };

  let closest: SupportedAspectRatio = "1:1";
  let minDiff = Infinity;

  for (const [key, value] of Object.entries(supported)) {
    const diff = Math.abs(ratio - value);
    if (diff < minDiff) {
      minDiff = diff;
      closest = key as SupportedAspectRatio;
    }
  }

  return closest;
}

