  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || []) as File[];
    if (files.length === 0) return;

    const newItems: ImageItem[] = await Promise.all(
      files.map(async (file) => {
        const url = URL.createObjectURL(file);
        const aspectRatio = await new Promise<SupportedAspectRatio>((resolve) => {
          const img = new Image();
          img.onload = () => resolve(getClosestAspectRatio(img.width, img.height));
          img.src = url;
        });

        return {
          id: Math.random().toString(36).substring(7),
          file,
          previewUrl: url,
          resultUrl: null,
          aspectRatio,
          status: 'idle' as const,
        };
      })
    );

    setImages(prev => [...prev, ...newItems]);
    if (!activeId && newItems.length > 0) {
      setActiveId(newItems[0].id);
    }
  };

  const processSingleImage = async (item: ImageItem, currentPrompt: string, referenceUrl?: string | null) => {
    setImages(prev => prev.map(img => img.id === item.id ? { ...img, status: 'processing', error: null } : img));

    try {
      const base64 = await fileToBase64(item.file);
      const result = await editImageBackground(base64, currentPrompt, item.aspectRatio, referenceUrl);
      setImages(prev => prev.map(img => img.id === item.id ? { ...img, status: 'completed', resultUrl: result, error: null } : img));
      return result;
    } catch (err: any) {
      const isAuthError = err.message === "API_KEY_EXPIRED";
      if (isAuthError) setHasKey(false);

      setImages(prev => prev.map(img => img.id === item.id ? { 
        ...img, 
        status: 'error', 
        error: isAuthError ? "API Key Expired" : (err.message || "Processing failed") 
      } : img));
      throw err;
    }
  };

  const handleBulkGenerate = async () => {
    if (images.length === 0 || !prompt.trim() || isBulkProcessing) return;

    setIsBulkProcessing(true);
    const pendingImages = images.filter(img => img.status !== 'completed');

    let masterReferenceUrl: string | null = null;
    const existingMaster = images.find(img => img.status === 'completed' && img.resultUrl);
    if (lockConsistency && existingMaster) {
      masterReferenceUrl = existingMaster.resultUrl;
    }

    for (const item of pendingImages) {
      try {
        const resultUrl = await processSingleImage(item, prompt, masterReferenceUrl);
        if (lockConsistency && !masterReferenceUrl) {
          masterReferenceUrl = resultUrl;
        }
      } catch (e) {
        console.error("Stopping bulk process due to error", e);
        break; 
      }
    }
    setIsBulkProcessing(false);
  };

  const getProcessedFilename = (originalName: string) => {
    const parts = originalName.split('.');
    if (parts.length > 1) {
      const ext = parts.pop();
      return `${parts.join('.')}_rendered.png`; // Always output as PNG for transparency support
    }
    return `${originalName}_rendered.png`;
  };

  const handleDownloadAll = () => {
    const completed = images.filter(img => img.resultUrl);
    if (completed.length === 0) return;

    completed.forEach((img, index) => {
      setTimeout(() => {
        const link = document.createElement('a');
        link.href = img.resultUrl!;
        link.download = getProcessedFilename(img.file.name);
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
      }, index * 300); // Slightly longer timeout for stability
    });
  };

  const handleRemoveImage = (id: string) => {
    setImages(prev => {
      const filtered = prev.filter(img => img.id !== id);
      if (activeId === id) {
        setActiveId(filtered.length > 0 ? filtered[0].id : null);
      }
      return filtered;
    });
  };

  const activeImage = images.find(img => img.id === activeId);
  const firstCompletedId = images.find(img => img.status === 'completed')?.id;
  const completedCount = images.filter(img => img.status === 'completed').length;

  if (hasKey === null) return <div className="min-h-screen bg-slate-950 flex items-center justify-center"><i className="fa-solid fa-spinner fa-spin text-4xl text-blue-500"></i></div>;
  if (hasKey === false) return <div className="min-h-screen bg-slate-950 pt-20"><ApiKeyGate onSuccess={() => setHasKey(true)} /></div>;

