import { GoogleGenAI } from "@google/genai";

export const MODEL_NAME = 'gemini-3-pro-image-preview';

export type SupportedAspectRatio = "1:1" | "3:4" | "4:3" | "9:16" | "16:9";

export async function editImageBackground(
  imageContent: string, 
  prompt: string,
  aspectRatio: SupportedAspectRatio = "1:1",
  referenceImageContent?: string | null 
): Promise<string> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Minimalist, strict instruction to prevent hallucinations
  const systemInstruction = `You are a precision image editor. 
  Your task is to replace the background of the provided image.

  CORE REQUIREMENTS:
  1. PRESERVE SUBJECT: The foreground person or main subject must remain exactly as they are. Do not change their appearance, pose, or clothing.
  2. PRESERVE LAYOUT: Keep the exact camera angle and crop.
  3. NO HALLUCINATIONS: Do not add any new furniture, objects, or architectural elements that are not in the original image.
  4. BACKGROUND SWAP: Replace the existing background environment with the one described in the prompt. If there is existing furniture, simply update its material/lighting to match the new background, but do not move it or add new furniture.
  5. NATURAL BLENDING: Ensure the lighting on the subject matches the new background.`;

  const contents: any = {
    parts: [
      {
        inlineData: {
          data: imageContent.split(',')[1],
          mimeType: 'image/png',
        },
      }
    ]
  };

  if (referenceImageContent) {
    contents.parts.push({
      inlineData: {
        data: referenceImageContent.split(',')[1],
        mimeType: 'image/png',
      },
    });

    contents.parts.push({
      text: `[CONSISTENCY MODE] 
      - The first image is the SOURCE.
      - The second image is the REFERENCE for the background style and lighting.
      - TASK: Replace the SOURCE's background with a version of the REFERENCE's style.
      - REQUIREMENT: Maintain the SOURCE's layout and furniture positions. Do not add new furniture.
      - THEME: ${prompt}.`,
    });
  } else {
    contents.parts.push({
      text: `[STRICT BACKGROUND SWAP] 
      - TASK: Replace the background with: ${prompt}.
      - IMPORTANT: Do not add any extra furniture or objects. Only change the style and lighting of the background as it exists.
      - RESOLUTION: 4K output.`,
    });
  }

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents,
      config: {
        systemInstruction,
        imageConfig: {
          aspectRatio,
          imageSize: "4K"
        }
      }
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }

    throw new Error("No image was generated. Please try a different description.");
  } catch (error: any) {
    if (error.message?.includes("Requested entity was not found")) {
      throw new Error("API_KEY_EXPIRED");
    }
    throw error;
  }
}

export async function fileToBase64(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = (error) => reject(error);
  });
}

export function getClosestAspectRatio(width: number, height: number): SupportedAspectRatio {
  const ratio = width / height;
  const supported = {
    "1:1": 1,
    "3:4": 3/4,
    "4:3": 4/3,
    "9:16": 9/16,
    "16:9": 16/9
  };

  let closest: SupportedAspectRatio = "1:1";
  let minDiff = Infinity;

  for (const [key, value] of Object.entries(supported)) {
    const diff = Math.abs(ratio - value);
    if (diff < minDiff) {
      minDiff = diff;
      closest = key as SupportedAspectRatio;
    }
  }

  return closest;
}

