import React, { useState, useEffect, useRef } from 'react';
import ApiKeyGate from './components/ApiKeyGate';
import { editImageBackground, fileToBase64, getClosestAspectRatio, SupportedAspectRatio } from './services/geminiService';
import { ImageItem, ProcessStatus } from './types';

const App: React.FC = () => {
  const [hasKey, setHasKey] = useState<boolean | null>(null);
  const [images, setImages] = useState<ImageItem[]>([]);
  const [activeId, setActiveId] = useState<string | null>(null);
  const [prompt, setPrompt] = useState<string>('');
  const [sliderPos, setSliderPos] = useState<number>(50);
  const [isBulkProcessing, setIsBulkProcessing] = useState(false);
  const [lockConsistency, setLockConsistency] = useState(true);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const checkKey = async () => {
      const selected = await window.aistudio.hasSelectedApiKey();
      setHasKey(selected);
    };
    checkKey();
  }, []);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || []) as File[];
    if (files.length === 0) return;

    const newItems: ImageItem[] = await Promise.all(
      files.map(async (file) => {
        const url = URL.createObjectURL(file);
        const aspectRatio = await new Promise<SupportedAspectRatio>((resolve) => {
          const img = new Image();
          img.onload = () => resolve(getClosestAspectRatio(img.width, img.height));
          img.src = url;
        });

        return {
          id: Math.random().toString(36).substring(7),
          file,
          previewUrl: url,
          resultUrl: null,
          aspectRatio,
          status: 'idle' as const,
        };
      })
    );

    setImages(prev => [...prev, ...newItems]);
    if (!activeId && newItems.length > 0) {
      setActiveId(newItems[0].id);
    }
  };

  const processSingleImage = async (item: ImageItem, currentPrompt: string, referenceUrl?: string | null) => {
    setImages(prev => prev.map(img => img.id === item.id ? { ...img, status: 'processing', error: null } : img));

    try {
      const base64 = await fileToBase64(item.file);
      const result = await editImageBackground(base64, currentPrompt, item.aspectRatio, referenceUrl);
      setImages(prev => prev.map(img => img.id === item.id ? { ...img, status: 'completed', resultUrl: result, error: null } : img));
      return result;
    } catch (err: any) {
      const isAuthError = err.message === "API_KEY_EXPIRED";
      if (isAuthError) setHasKey(false);

      setImages(prev => prev.map(img => img.id === item.id ? { 
        ...img, 
        status: 'error', 
        error: isAuthError ? "API Key Expired" : (err.message || "Processing failed") 
      } : img));
      throw err;
    }
  };

  const handleBulkGenerate = async () => {
    if (images.length === 0 || !prompt.trim() || isBulkProcessing) return;

    setIsBulkProcessing(true);
    const pendingImages = images.filter(img => img.status !== 'completed');

    let masterReferenceUrl: string | null = null;
    const existingMaster = images.find(img => img.status === 'completed' && img.resultUrl);
    if (lockConsistency && existingMaster) {
      masterReferenceUrl = existingMaster.resultUrl;
    }

    for (const item of pendingImages) {
      try {
        const resultUrl = await processSingleImage(item, prompt, masterReferenceUrl);
        if (lockConsistency && !masterReferenceUrl) {
          masterReferenceUrl = resultUrl;
        }
      } catch (e) {
        console.error("Stopping bulk process due to error", e);
        break; 
      }
    }
    setIsBulkProcessing(false);
  };

  const handleDownloadAll = () => {
    const completed = images.filter(img => img.resultUrl);
    if (completed.length === 0) return;

    completed.forEach((img, index) => {
      setTimeout(() => {
        const link = document.createElement('a');
        link.href = img.resultUrl!;
        link.download = `result-${img.id}.png`;
        link.click();
      }, index * 200);
    });
  };

  const activeImage = images.find(img => img.id === activeId);

  if (hasKey === false) {
    return <ApiKeyGate onSuccess={() => setHasKey(true)} />;
  }

  if (hasKey === null) {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center text-slate-400">
        <div className="flex flex-col items-center gap-4">
          <div className="w-8 h-8 border-4 border-blue-500/20 border-t-blue-500 rounded-full animate-spin"></div>
          <p>Checking authentication...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-900 text-slate-100 font-sans">
      <header className="border-b border-slate-800 bg-slate-900/50 backdrop-blur-md sticky top-0 z-10">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center shadow-lg shadow-blue-500/20">
              <i className="fa-solid fa-wand-magic-sparkles text-xl text-white"></i>
            </div>
            <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-white to-slate-400">
              StudioPro <span className="text-blue-500">AI</span>
            </h1>
          </div>
          <div className="flex gap-4">
            <button 
              onClick={() => fileInputRef.current?.click()}
              className="px-4 py-2 bg-slate-800 hover:bg-slate-700 rounded-lg text-sm font-medium transition-colors border border-slate-700"
            >
              <i className="fa-solid fa-plus mr-2"></i> Add Images
            </button>
            <button 
              onClick={handleDownloadAll}
              disabled={images.filter(img => img.resultUrl).length === 0}
              className="px-4 py-2 bg-blue-600 hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed rounded-lg text-sm font-medium transition-colors"
            >
              <i className="fa-solid fa-download mr-2"></i> Download All
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 py-8 grid grid-cols-1 lg:grid-cols-12 gap-8">
        <div className="lg:col-span-3 space-y-6">
          <div className="bg-slate-800/50 rounded-2xl border border-slate-700 p-4">
            <h2 className="text-sm font-semibold text-slate-400 uppercase tracking-wider mb-4 px-2">Gallery</h2>
            <div className="space-y-2 max-h-[60vh] overflow-y-auto pr-2 custom-scrollbar">
              {images.map(img => (
                <button
                  key={img.id}
                  onClick={() => setActiveId(img.id)}
                  className={`w-full group relative aspect-square rounded-xl overflow-hidden border-2 transition-all ${
                    activeId === img.id ? 'border-blue-500 ring-4 ring-blue-500/20' : 'border-slate-700 hover:border-slate-600'
                  }`}
                >
                  <img src={img.previewUrl} className="w-full h-full object-cover" alt="Preview" />
                  {img.status === 'processing' && (
                    <div className="absolute inset-0 bg-slate-900/60 flex items-center justify-center">
                      <i className="fa-solid fa-circle-notch fa-spin text-blue-500 text-xl"></i>
                    </div>
                  )}
                  {img.status === 'completed' && (
                    <div className="absolute top-2 right-2 w-5 h-5 bg-green-500 rounded-full flex items-center justify-center text-[10px] text-white">
                      <i className="fa-solid fa-check"></i>
                    </div>
                  )}
                  {img.status === 'error' && (
                    <div className="absolute top-2 right-2 w-5 h-5 bg-red-500 rounded-full flex items-center justify-center text-[10px] text-white">
                      <i className="fa-solid fa-exclamation"></i>
                    </div>
                  )}
                </button>
              ))}
              {images.length === 0 && (
                <div className="aspect-square rounded-xl border-2 border-dashed border-slate-700 flex flex-col items-center justify-center text-slate-500 gap-2 p-4 text-center">
                  <i className="fa-solid fa-cloud-arrow-up text-2xl"></i>
                  <span className="text-xs">No images uploaded</span>
                </div>
              )}
            </div>
          </div>
        </div>

        <div className="lg:col-span-6 space-y-6">
          <div className="bg-slate-800/50 rounded-2xl border border-slate-700 overflow-hidden relative min-h-[500px] flex items-center justify-center">
            {activeImage ? (
              <div className="relative w-full h-full flex items-center justify-center p-8">
                {activeImage.resultUrl ? (
                  <div className="relative w-full max-w-lg aspect-square group">
                    <div className="absolute inset-0 select-none pointer-events-none">
                       <img src={activeImage.previewUrl} className="w-full h-full object-contain" alt="Original" />
                    </div>
                    <div 
                      className="absolute inset-0 overflow-hidden select-none pointer-events-none"
                      style={{ clipPath: `inset(0 ${100 - sliderPos}% 0 0)` }}
                    >
                      <img src={activeImage.resultUrl} className="w-full h-full object-contain" alt="Result" />
                    </div>

                    <input
                      type="range"
                      min="0"
                      max="100"
                      value={sliderPos}
                      onChange={(e) => setSliderPos(parseInt(e.target.value))}
                      className="absolute inset-0 opacity-0 cursor-ew-resize z-20"
                    />
                    <div 
                      className="absolute top-0 bottom-0 w-1 bg-white shadow-xl z-10 pointer-events-none"
                      style={{ left: `${sliderPos}%` }}
                    >
                      <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-8 h-8 bg-white rounded-full flex items-center justify-center text-slate-900 shadow-2xl">
                        <i className="fa-solid fa-arrows-left-right text-xs"></i>
                      </div>
                    </div>

                    <div className="absolute bottom-4 left-4 bg-slate-900/80 backdrop-blur px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-wider border border-white/10">
                      Slide to Compare
                    </div>
                  </div>
                ) : (
                  <div className="max-w-lg w-full aspect-square rounded-xl overflow-hidden shadow-2xl border border-white/5">
                    <img src={activeImage.previewUrl} className="w-full h-full object-cover" alt="Editor Preview" />
                  </div>
                )}

                {activeImage.status === 'processing' && (
                  <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-[2px] flex items-center justify-center">
                    <div className="bg-slate-800 p-6 rounded-2xl border border-slate-700 shadow-2xl text-center space-y-4">
                      <div className="w-12 h-12 border-4 border-blue-500/20 border-t-blue-500 rounded-full animate-spin mx-auto"></div>
                      <div>
                        <p className="font-semibold text-white">Generating Background</p>
                        <p className="text-sm text-slate-400">Gemini is crafting your image...</p>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            ) : (
              <div className="text-center p-12 space-y-6">
                <div className="w-24 h-24 bg-slate-700/50 rounded-3xl flex items-center justify-center mx-auto text-slate-500">
                  <i className="fa-solid fa-images text-4xl"></i>
                </div>
                <div>
                  <h3 className="text-xl font-semibold mb-2">No Image Selected</h3>
                  <p className="text-slate-400 max-w-xs mx-auto">
                    Upload your professional portraits to start editing backgrounds with AI.
                  </p>
                </div>
                <button 
                  onClick={() => fileInputRef.current?.click()}
                  className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-3 rounded-xl font-semibold transition-all shadow-lg shadow-blue-500/20"
                >
                  Upload Photos
                </button>
              </div>
            )}
          </div>
        </div>

        <div className="lg:col-span-3 space-y-6">
          <div className="bg-slate-800/50 rounded-2xl border border-slate-700 p-6 space-y-6">
            <div className="space-y-4">
              <label className="text-sm font-semibold text-slate-400 uppercase tracking-wider block">
                Background Prompt
              </label>
              <textarea
                value={prompt}
                onChange={(e) => setPrompt(e.target.value)}
                placeholder="e.g., A minimalist modern office with large windows..."
                className="w-full bg-slate-900 border border-slate-700 rounded-xl p-4 text-sm focus:ring-2 focus:ring-blue-500 outline-none min-h-[120px] transition-all"
              />
            </div>

            <div className="space-y-4 pt-4 border-t border-slate-700">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <i className="fa-solid fa-layer-group text-blue-400"></i>
                  <span className="text-sm font-medium">Style Consistency</span>
                </div>
                <button
                  onClick={() => setLockConsistency(!lockConsistency)}
                  className={`w-12 h-6 rounded-full transition-colors relative ${lockConsistency ? 'bg-blue-600' : 'bg-slate-700'}`}
                >
                  <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${lockConsistency ? 'left-7' : 'left-1'}`} />
                </button>
              </div>
              <p className="text-[11px] text-slate-500 leading-relaxed">
                When enabled, subsequent images will use the first generated background as a reference for consistent lighting and style.
              </p>
            </div>

            <div className="space-y-3 pt-4">
              <button
                disabled={!activeImage || !prompt.trim() || activeImage.status === 'processing' || isBulkProcessing}
                onClick={() => activeImage && processSingleImage(activeImage, prompt)}
                className="w-full py-4 bg-slate-700 hover:bg-slate-600 disabled:opacity-50 disabled:cursor-not-allowed rounded-xl font-bold transition-all border border-slate-600 flex items-center justify-center gap-2"
              >
                {activeImage?.status === 'processing' ? (
                  <i className="fa-solid fa-circle-notch fa-spin"></i>
                ) : (
                  <i className="fa-solid fa-wand-magic-sparkles"></i>
                )}
                Regenerate Selected
              </button>

              <button
                disabled={images.length === 0 || !prompt.trim() || isBulkProcessing}
                onClick={handleBulkGenerate}
                className="w-full py-4 bg-blue-600 hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed rounded-xl font-bold transition-all shadow-lg shadow-blue-500/25 flex items-center justify-center gap-2"
              >
                {isBulkProcessing ? (
                  <i className="fa-solid fa-circle-notch fa-spin"></i>
                ) : (
                  <i className="fa-solid fa-bolt"></i>
                )}
                Process All Images
              </button>
            </div>

            {activeImage?.error && (
              <div className="bg-red-500/10 border border-red-500/20 p-4 rounded-xl text-red-400 text-xs flex gap-3">
                <i className="fa-solid fa-circle-exclamation mt-0.5"></i>
                <span>{activeImage.error}</span>
              </div>
            )}
          </div>
        </div>
      </main>

      <input
        type="file"
        ref={fileInputRef}
        onChange={handleFileChange}
        multiple
        accept="image/*"
        className="hidden"
      />
    </div>
  );
};

