        <div className="lg:col-span-6 space-y-6">
          <div className="bg-slate-800/50 rounded-2xl border border-slate-700 overflow-hidden relative min-h-[500px] flex items-center justify-center">
            {activeImage ? (
              <div className="relative w-full h-full flex items-center justify-center p-8">
                {activeImage.resultUrl ? (
                  <div className="relative w-full max-w-lg aspect-square group">
                    <div className="absolute inset-0 select-none pointer-events-none">
                       <img src={activeImage.previewUrl} className="w-full h-full object-contain" alt="Original" />
                    </div>
                    <div 
                      className="absolute inset-0 overflow-hidden select-none pointer-events-none"
                      style={{ clipPath: `inset(0 ${100 - sliderPos}% 0 0)` }}
                    >
                      <img src={activeImage.resultUrl} className="w-full h-full object-contain" alt="Result" />
                    </div>

                    <input
                      type="range"
                      min="0"
