                disabled={images.length === 0 || !prompt.trim() || isBulkProcessing}
                onClick={handleBulkGenerate}
                className="w-full py-5 bg-blue-600 hover:bg-blue-500 disabled:opacity-30 disabled:cursor-not-allowed rounded-2xl font-bold transition-all shadow-xl shadow-blue-500/20 flex items-center justify-center gap-3 text-sm"
              >
                {isBulkProcessing ? <i className="fa-solid fa-spinner fa-spin"></i> : <i className="fa-solid fa-bolt"></i>}
                Batch Process All
              </button>
            </div>

            {activeImage?.error && (
              <div className="bg-red-500/5 border border-red-500/20 p-5 rounded-2xl text-red-400 text-[11px] flex gap-3 leading-relaxed">
                <i className="fa-solid fa-triangle-exclamation mt-0.5"></i>
                <span>{activeImage.error}</span>
              </div>
            )}
          </div>

          <div className="p-6 bg-blue-500/5 rounded-3xl border border-blue-500/10 space-y-4">
             <h4 className="text-[10px] font-bold text-blue-400 uppercase tracking-widest">Workflow Insights</h4>
             <ul className="space-y-3 text-[10px] text-slate-500 font-medium">
                <li className="flex gap-2"><i className="fa-solid fa-check text-blue-500/50"></i> Original crops are pixel-locked.</li>
                <li className="flex gap-2"><i className="fa-solid fa-check text-blue-500/50"></i> Filenames are preserved on export.</li>
                <li className="flex gap-2"><i className="fa-solid fa-check text-blue-500/50"></i> Reference image only affects lighting.</li>
             </ul>
          </div>
        </div>
      </main>

      <input
        type="file"
        ref={fileInputRef}
        onChange={handleFileChange}
        multiple
        accept="image/*"
        className="hidden"
      />
    </div>
  );
};

