export const MODEL_NAME = 'gemini-3-pro-image-preview';

export type SupportedAspectRatio = "1:1" | "3:4" | "4:3" | "9:16" | "16:9";

export async function editImageBackground(
  imageContent: string, 
  prompt: string,
  aspectRatio: SupportedAspectRatio = "1:1",
  referenceImageContent?: string | null 
): Promise<string> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const systemInstruction = `You are a High-Precision Visual Effects Compositor. 
  Your primary directive is to swap the background while maintaining a PERFECT SPATIAL LOCK on the subject.

  STRICT SPATIAL & OBJECT RULES:
  1. PIXEL-ANCHOR SUBJECT: The subject (person or object) must maintain the EXACT same size, position, and proportion relative to the frame boundaries as the original. DO NOT zoom, scale, or move the subject.
  2. NO FURNITURE HALLUCINATION: Do NOT add chairs, tables, lamps, or any furniture that is not already present in the source image.
  3. CLEAN PLATE ARCHITECTURE: If the source background is empty, the new background must also be empty of objects. Only change the walls, floors, and windows to match the theme.
  4. OPTICAL SYNC: Match the horizon line, tilt, and focal length of the source image exactly.
  5. MATERIAL LOCK: When using a reference, ONLY copy the materials (e.g., color of wood, texture of stone) and lighting. NEVER copy physical objects or furniture from the reference into the source.`;

  const contents: any = {
    parts: [
      {
        inlineData: {
          data: imageContent.split(',')[1],
          mimeType: 'image/png',
        },
      }
    ]
  };

  if (referenceImageContent) {
    contents.parts.push({
      inlineData: {
        data: referenceImageContent.split(',')[1],
        mimeType: 'image/png',
      },
    });

    contents.parts.push({
      text: `[STRICT MATERIAL & PERSPECTIVE SYNC] 
      - SOURCE: This is the template for CROP and SUBJECT SIZE. Maintain subject proportion 1:1.
      - MASTER STYLE: Use the second image ONLY for LIGHTING and MATERIAL TEXTURES.
      - FORBIDDEN: Do NOT copy any chairs, tables, or props from the MASTER. 
      - TASK: Render an empty version of the MASTER environment "${prompt}" behind the SOURCE subject. Match the SOURCE's camera angle perfectly.`,
    });
  } else {
    contents.parts.push({
      text: `[ARCHITECTURAL BACKGROUND SWAP] 
      - Replace only the background with: "${prompt}".
      - KEEP SUBJECT SIZE AND CROP IDENTICAL TO SOURCE.
      - Render only the structural environment (walls/floor/lighting). Do not add any furniture or secondary objects.
      - 4K resolution output.`,
    });
  }

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents,
      config: {
        systemInstruction,
        imageConfig: {
          aspectRatio,
          imageSize: "4K"
        }
      }
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }

    throw new Error("Spatial lock failed. Please try a simpler description.");
  } catch (error: any) {
    if (error.message?.includes("Requested entity was not found")) {
      throw new Error("API_KEY_EXPIRED");
    }
    throw error;
  }
}

export async function fileToBase64(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = (error) => reject(error);
  });
}

export function getClosestAspectRatio(width: number, height: number): SupportedAspectRatio {
  const ratio = width / height;
  const supported = {
    "1:1": 1,
    "3:4": 3/4,
    "4:3": 4/3,
    "9:16": 9/16,
    "16:9": 16/9
  };

  let closest: SupportedAspectRatio = "1:1";
  let minDiff = Infinity;

  for (const [key, value] of Object.entries(supported)) {
    const diff = Math.abs(ratio - value);
    if (diff < minDiff) {
      minDiff = diff;
      closest = key as SupportedAspectRatio;
    }
  }

  return closest;
}

import React, { useState, useEffect, useRef } from 'react';
import ApiKeyGate from './components/ApiKeyGate';
import { editImageBackground, fileToBase64, getClosestAspectRatio, SupportedAspectRatio } from './services/geminiService';
import { ImageItem, ProcessStatus } from './types';

const App: React.FC = () => {
  const [hasKey, setHasKey] = useState<boolean | null>(null);
  const [images, setImages] = useState<ImageItem[]>([]);
  const [activeId, setActiveId] = useState<string | null>(null);
  const [prompt, setPrompt] = useState<string>('');
  const [sliderPos, setSliderPos] = useState<number>(50);
  const [isBulkProcessing, setIsBulkProcessing] = useState(false);
  const [lockConsistency, setLockConsistency] = useState(true);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const checkKey = async () => {
      const selected = await window.aistudio.hasSelectedApiKey();
      setHasKey(selected);
    };
    checkKey();
  }, []);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || []) as File[];
    if (files.length === 0) return;

    const newItems: ImageItem[] = await Promise.all(
      files.map(async (file) => {
        const url = URL.createObjectURL(file);
        const aspectRatio = await new Promise<SupportedAspectRatio>((resolve) => {
          const img = new Image();
          img.onload = () => resolve(getClosestAspectRatio(img.width, img.height));
          img.src = url;
        });

        return {
          id: Math.random().toString(36).substring(7),
          file,
          previewUrl: url,
          resultUrl: null,
          aspectRatio,
          status: 'idle' as const,
        };
      })
    );

    setImages(prev => [...prev, ...newItems]);
    if (!activeId && newItems.length > 0) {
      setActiveId(newItems[0].id);
    }
  };

  const processSingleImage = async (item: ImageItem, currentPrompt: string, referenceUrl?: string | null) => {
    setImages(prev => prev.map(img => img.id === item.id ? { ...img, status: 'processing', error: null } : img));

    try {
      const base64 = await fileToBase64(item.file);
      const result = await editImageBackground(base64, currentPrompt, item.aspectRatio, referenceUrl);
      setImages(prev => prev.map(img => img.id === item.id ? { ...img, status: 'completed', resultUrl: result, error: null } : img));
      return result;
    } catch (err: any) {
      const isAuthError = err.message === "API_KEY_EXPIRED";
      if (isAuthError) setHasKey(false);

      setImages(prev => prev.map(img => img.id === item.id ? { 
        ...img, 
        status: 'error', 
        error: isAuthError ? "API Key Expired" : (err.message || "Processing failed") 
      } : img));
      throw err;
    }
  };

  const handleBulkGenerate = async () => {
    if (images.length === 0 || !prompt.trim() || isBulkProcessing) return;

    setIsBulkProcessing(true);
    const pendingImages = images.filter(img => img.status !== 'completed');

    let masterReferenceUrl: string | null = null;
    const existingMaster = images.find(img => img.status === 'completed' && img.resultUrl);
    if (lockConsistency && existingMaster) {
      masterReferenceUrl = existingMaster.resultUrl;
    }

    for (const item of pendingImages) {
      try {
        const resultUrl = await processSingleImage(item, prompt, masterReferenceUrl);
        if (lockConsistency && !masterReferenceUrl) {
          masterReferenceUrl = resultUrl;
        }
      } catch (e) {
        console.error("Stopping batch due to spatial lock error", e);
        break; 
      }
    }
    setIsBulkProcessing(false);
  };

  const handleDownloadAll = () => {
    const completed = images.filter(img => img.resultUrl);
    if (completed.length === 0) return;

    completed.forEach((img, index) => {
      setTimeout(() => {
        const link = document.createElement('a');
        link.href = img.resultUrl!;
        link.download = img.file.name;
        link.click();
      }, index * 300);
    });
  };

  const activeImage = images.find(img => img.id === activeId);

  if (hasKey === false) {
    return <ApiKeyGate onSuccess={() => setHasKey(true)} />;
  }

  if (hasKey === null) {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center text-slate-400">
        <div className="flex flex-col items-center gap-4">
          <div className="w-8 h-8 border-4 border-blue-500/20 border-t-blue-500 rounded-full animate-spin"></div>
          <p>Initializing Spatial Anchor Engine...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#0f172a] text-slate-100 font-sans">
      <header className="border-b border-slate-800 bg-slate-900/50 backdrop-blur-md sticky top-0 z-10">
        <div className="max-w-7xl mx-auto px-6 h-20 flex items-center justify-between">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 bg-blue-600 rounded-2xl flex items-center justify-center shadow-lg shadow-blue-500/20">
              <i className="fa-solid fa-anchor text-xl text-white"></i>
            </div>
            <div>
              <h1 className="text-xl font-bold tracking-tight">
                StudioPro <span className="text-blue-500">Anchor</span>
              </h1>
              <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">Spatially Locked Compositor</p>
            </div>
          </div>
          <div className="flex gap-3">
            <button 
              onClick={() => fileInputRef.current?.click()}
              className="px-5 py-2.5 bg-slate-800 hover:bg-slate-700 rounded-xl text-sm font-semibold transition-all border border-slate-700 flex items-center gap-2"
            >
              <i className="fa-solid fa-plus text-blue-400"></i> Import Batch
            </button>
            <button 
              onClick={handleDownloadAll}
              disabled={images.filter(img => img.resultUrl).length === 0}
              className="px-5 py-2.5 bg-blue-600 hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed rounded-xl text-sm font-semibold transition-all shadow-lg shadow-blue-500/25 flex items-center gap-2"
            >
              <i className="fa-solid fa-cloud-arrow-down"></i> Export Results
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-6 py-10 grid grid-cols-1 lg:grid-cols-12 gap-10">
        <div className="lg:col-span-3 space-y-6">
          <div className="bg-slate-900/50 rounded-3xl border border-slate-800 p-5">
            <h2 className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-4 px-2">Batch Queue</h2>
            <div className="space-y-3 max-h-[65vh] overflow-y-auto pr-2 custom-scrollbar">
              {images.map(img => (
                <button
                  key={img.id}
                  onClick={() => setActiveId(img.id)}
                  className={`w-full group relative aspect-square rounded-2xl overflow-hidden border-2 transition-all ${
                    activeId === img.id ? 'border-blue-500 ring-4 ring-blue-500/10' : 'border-slate-800 hover:border-slate-700'
                  }`}
                >
                  <img src={img.previewUrl} className="w-full h-full object-cover" alt="Preview" />
                  <div className="absolute inset-x-0 bottom-0 bg-black/60 backdrop-blur-sm p-2 text-[8px] font-bold text-slate-300 truncate">
                    {img.file.name}
                  </div>
                  {img.status === 'processing' && (
                    <div className="absolute inset-0 bg-slate-900/60 flex items-center justify-center">
                      <i className="fa-solid fa-circle-notch fa-spin text-blue-500 text-xl"></i>
                    </div>
                  )}
                  {img.status === 'completed' && (
                    <div className="absolute top-2 right-2 w-6 h-6 bg-green-500 rounded-full flex items-center justify-center text-[10px] text-white shadow-lg">
                      <i className="fa-solid fa-check"></i>
                    </div>
                  )}
                </button>
              ))}
              {images.length === 0 && (
                <div className="aspect-square rounded-2xl border-2 border-dashed border-slate-800 flex flex-col items-center justify-center text-slate-600 gap-3 p-6 text-center">
                  <i className="fa-solid fa-images text-3xl opacity-20"></i>
                  <span className="text-[10px] font-bold uppercase tracking-widest">Queue Empty</span>
                </div>
              )}
            </div>
          </div>
        </div>

        <div className="lg:col-span-6 space-y-6">
          <div className="bg-slate-900/80 rounded-[40px] border border-slate-800 overflow-hidden relative min-h-[580px] flex items-center justify-center shadow-2xl">
            {activeImage ? (
              <div className="relative w-full h-full flex items-center justify-center p-6">
                {activeImage.resultUrl ? (
                  <div className="relative w-full h-full max-h-[500px] aspect-square group shadow-2xl rounded-2xl overflow-hidden">
                    <img src={activeImage.previewUrl} className="absolute inset-0 w-full h-full object-contain" alt="Original" />
                    <div 
                      className="absolute inset-0 overflow-hidden"
                      style={{ clipPath: `inset(0 ${100 - sliderPos}% 0 0)` }}
                    >
                      <img src={activeImage.resultUrl} className="w-full h-full object-contain" alt="Result" />
                    </div>

                    <input
                      type="range"
                      min="0"
                      max="100"
                      value={sliderPos}
                      onChange={(e) => setSliderPos(parseInt(e.target.value))}
                      className="absolute inset-0 opacity-0 cursor-ew-resize z-20"
                    />
                    <div 
                      className="absolute top-0 bottom-0 w-1 bg-white shadow-[0_0_20px_rgba(255,255,255,0.4)] z-10 pointer-events-none"
                      style={{ left: `${sliderPos}%` }}
                    >
                      <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-10 h-10 bg-white rounded-full flex items-center justify-center text-slate-900 shadow-2xl">
                        <i className="fa-solid fa-arrows-left-right text-sm"></i>
                      </div>
                    </div>

                    <div className="absolute bottom-6 left-6 bg-black/50 backdrop-blur-xl px-4 py-2 rounded-full text-[10px] font-bold uppercase tracking-[0.2em] border border-white/10 text-white flex items-center gap-2">
                      <i className="fa-solid fa-lock text-blue-400"></i> 
                      Pixel-Anchor Locked
                    </div>
                  </div>
                ) : (
                  <div className="w-full max-h-[500px] aspect-square rounded-3xl overflow-hidden border border-slate-800">
                    <img src={activeImage.previewUrl} className="w-full h-full object-contain" alt="Original Template" />
                  </div>
                )}

                {activeImage.status === 'processing' && (
                  <div className="absolute inset-0 bg-slate-950/40 backdrop-blur-md flex items-center justify-center z-30">
                    <div className="bg-slate-900 p-8 rounded-[32px] border border-slate-800 shadow-2xl text-center space-y-6 max-w-xs">
                      <div className="w-16 h-16 border-4 border-blue-500/10 border-t-blue-500 rounded-full animate-spin mx-auto"></div>
                      <div>
                        <p className="font-bold text-white text-lg">Locking Spatial Anchors</p>
                        <p className="text-xs text-slate-500 mt-1 uppercase tracking-widest font-bold">Matching Subject Proportion...</p>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            ) : (
              <div className="text-center p-12 space-y-8">
                <div className="w-28 h-28 bg-slate-800/30 rounded-[40px] flex items-center justify-center mx-auto text-slate-700 border border-slate-800">
                  <i className="fa-solid fa-anchor text-4xl"></i>
                </div>
                <div>
                  <h3 className="text-2xl font-bold mb-3 tracking-tight">Precision Studio</h3>
                  <p className="text-slate-500 max-w-xs mx-auto text-sm leading-relaxed">
                    Import your product or lifestyle shots. The subject size and frame position will be anchored 1:1.
                  </p>
                </div>
                <button 
                  onClick={() => fileInputRef.current?.click()}
                  className="bg-blue-600 hover:bg-blue-500 text-white px-8 py-4 rounded-2xl font-bold transition-all shadow-xl shadow-blue-500/20 active:scale-95"
                >
                  Start Session
                </button>
              </div>
            )}
          </div>
        </div>

        <div className="lg:col-span-3 space-y-6">
          <div className="bg-slate-900/50 rounded-3xl border border-slate-800 p-8 space-y-8">
            <div className="space-y-4">
              <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest block px-1">
                Environment Materials
              </label>
              <textarea
                value={prompt}
                onChange={(e) => setPrompt(e.target.value)}
                placeholder="Describe only materials (e.g. Concrete floors, beige walls)..."
                className="w-full bg-black/40 border border-slate-800 rounded-2xl p-5 text-sm text-slate-200 focus:ring-2 focus:ring-blue-500/50 outline-none min-h-[160px] transition-all resize-none placeholder:text-slate-700"
              />
            </div>

            <div className="space-y-4 pt-6 border-t border-slate-800">
              <div className="flex items-center justify-between">
                <div>
                  <span className="text-xs font-bold text-slate-300">Spatial Consistency</span>
                  <p className="text-[9px] text-slate-600 font-bold uppercase mt-0.5 tracking-tighter">Sync lighting & materials</p>
                </div>
                <button
                  onClick={() => setLockConsistency(!lockConsistency)}
                  className={`w-12 h-6 rounded-full transition-all relative ${lockConsistency ? 'bg-blue-600' : 'bg-slate-800'}`}
                >
                  <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${lockConsistency ? 'left-7' : 'left-1'}`} />
                </button>
              </div>
            </div>

            <div className="space-y-3">
              <button
                disabled={!activeImage || !prompt.trim() || activeImage.status === 'processing' || isBulkProcessing}
                onClick={() => activeImage && processSingleImage(activeImage, prompt)}
                className="w-full py-4 bg-slate-800 hover:bg-slate-700 disabled:opacity-30 disabled:cursor-not-allowed rounded-2xl font-bold transition-all border border-slate-700 flex items-center justify-center gap-2 text-sm"
              >
                {activeImage?.status === 'processing' ? <i className="fa-solid fa-spinner fa-spin"></i> : <i className="fa-solid fa-wand-sparkles text-blue-400"></i>}
                Process Active
              </button>

              <button
                disabled={images.length === 0 || !prompt.trim() || isBulkProcessing}
                onClick={handleBulkGenerate}
                className="w-full py-5 bg-blue-600 hover:bg-blue-500 disabled:opacity-30 disabled:cursor-not-allowed rounded-2xl font-bold transition-all shadow-xl shadow-blue-500/20 flex items-center justify-center gap-3 text-sm"
              >
                {isBulkProcessing ? <i className="fa-solid fa-spinner fa-spin"></i> : <i className="fa-solid fa-bolt"></i>}
                Batch Sync Process
              </button>
            </div>
          </div>

          <div className="p-6 bg-blue-500/5 rounded-3xl border border-blue-500/10 space-y-4">
             <h4 className="text-[10px] font-bold text-blue-400 uppercase tracking-widest">Pixel-Anchor Intelligence</h4>
             <ul className="space-y-3 text-[10px] text-slate-500 font-medium">
                <li className="flex gap-2"><i className="fa-solid fa-check text-blue-500/50"></i> Subject proportion locked 1:1.</li>
                <li className="flex gap-2"><i className="fa-solid fa-check text-blue-500/50"></i> No furniture hallucination protocol.</li>
                <li className="flex gap-2"><i className="fa-solid fa-check text-blue-500/50"></i> Clean-plate architectural mode.</li>
             </ul>
          </div>
        </div>
      </main>

      <input
        type="file"
        ref={fileInputRef}
        onChange={handleFileChange}
        multiple
        accept="image/*"
        className="hidden"
      />
    </div>
  );
};

export default App;

export type ProcessStatus = 'idle' | 'processing' | 'completed' | 'error';

export interface ImageItem {
  id: string;
  file: File;
  previewUrl: string;
  resultUrl: string | null;
  aspectRatio: "1:1" | "3:4" | "4:3" | "9:16" | "16:9";
  status: ProcessStatus;
  error?: string | null;
}

export interface GenerationState {
  isGenerating: boolean;
  error: string | null;
}

export interface ImagePreview {
  file: File;
  previewUrl: string;
}

declare global {
  interface AIStudio {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  }

  interface Window {
    // Removed readonly modifier to match the platform's global declaration and resolve the modifier mismatch error
    aistudio: AIStudio;
  }
}
